//! Generated schema facts follow the production renderer.
#![expect(
    clippy::disallowed_types,
    clippy::disallowed_macros,
    reason = "ordinary code generation test formats source at its build-time workspace path"
)]

use std::{
    fs,
    io::Write,
    path::Path,
    process::{Command, Stdio},
};

#[test]
fn generated_schema_costs_follow_the_production_renderer() {
    let facts = super::renderer::measure().expect("production renderer has finite costs");
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let source = format!(
        "//! Generated by `schema_costs::tests`; do not edit.\n\nuse smith_domain::run::SchemaCosts;\n\npub(crate) const COSTS: SchemaCosts = {facts:#?};\n"
    );
    let mut formatter = Command::new("rustfmt")
        .args(["--edition", "2024", "--config-path"])
        .arg(root.join("../.."))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .expect("rustfmt is available for the writer");
    formatter.stdin.take().expect("formatter input").write_all(source.as_bytes()).expect("write source");
    let output = formatter.wait_with_output().expect("formatter completes");
    assert!(output.status.success(), "generated source formats");
    let generated = root.join("src/generated_schema_costs.rs");
    let write = std::env::var_os("SKEIN_CODEGEN_WRITE").as_deref() == Some(std::ffi::OsStr::new("1"));
    if write {
        fs::write(&generated, &output.stdout).expect("write generated costs");
    }
    if !write {
        assert_eq!(super::schema_costs().expect("constant costs"), facts, "compiled facts match the renderer");
    }
    assert_eq!(
        fs::read_to_string(generated).expect("generated costs"),
        String::from_utf8(output.stdout).expect("formatted Rust is UTF-8"),
        "regenerate with SKEIN_CODEGEN_WRITE=1"
    );
}
